pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address owner, address spender, uint256 value, uint8 v, bytes32 r, bytes32 s) internal {
        vm.assume(owner != address(0));
        bool reverted;
        try c.permit(owner, spender, value, block.timestamp, v, r, s) { reverted = false; }
        catch { reverted = true; }
        uint256 allowanceAfter;
        try c.allowance(owner, spender) returns (uint256 __r) { allowanceAfter = __r; } catch { return; }
        assertTrue(reverted && allowanceAfter == 0);
    }

    function testFuzz_run(address owner, address spender, uint256 value, uint8 v, bytes32 r, bytes32 s) public {
        vm.assume(owner.code.length == 0 && uint160(owner) > 0xffff && owner != address(this) && owner != address(c) && owner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && owner != 0x000000000000000000636F6e736F6c652e6c6f67 && owner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && owner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(spender.code.length == 0 && uint160(spender) > 0xffff && spender != address(this) && spender != address(c) && spender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && spender != 0x000000000000000000636F6e736F6c652e6c6f67 && spender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && spender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(owner, spender, value, v, r, s);
    }

    receive() external payable {}
}
